//! The core PyYAML engine (`services::pyyaml`, which replaced workstream B's private port at the merge: PORTING.md A-7)
//! against CPython + PyYAML 6.0.3 answers for the same documents
//! (tests/fixtures/aiperf/pyyaml_golden.json, generated by tests/fixtures/aiperf/gen_pyyaml_golden.py): loaded values,
//! error classes and texts (`str(e)`, `problem`, mark line), `yaml.compose` key lines and `safe_dump` output.
#![allow(
    clippy::unwrap_used,
    clippy::expect_used,
    clippy::panic,
    clippy::needless_pass_by_value
)]

use nemo_console::services::pyfmt::{float_repr, json_dumps};
use nemo_console::services::pyyaml::{self, DumpOpts, NodeKind, PyValue as Yv, YamlError};
use serde_json::{Value, json};

fn canon(v: &Yv) -> Value {
    match v {
        Yv::None => json!(["null"]),
        Yv::Bool(b) => json!(["bool", b]),
        Yv::Int(i) => json!(["int", i.to_string()]),
        Yv::BigInt(s) => json!(["int", s]),
        Yv::Float(f) => json!(["float", float_repr(*f)]),
        Yv::Str(s) => json!(["str", s]),
        Yv::Bytes(b) => json!(["bytes", hex::encode(b)]),
        Yv::Date { .. } => json!(["date", v.py_str(), v.repr()]),
        Yv::DateTime(_) => json!(["datetime", v.py_str(), v.repr()]),
        Yv::Tuple(items) => json!(["tuple", items.iter().map(canon).collect::<Vec<_>>()]),
        Yv::List(items) => json!(["list", items.iter().map(canon).collect::<Vec<_>>()]),
        Yv::Set(items) => {
            let mut s: Vec<String> = items.iter().map(|x| json_dumps(&canon(x))).collect();
            s.sort();
            json!(["set", s])
        }
        Yv::Dict(items) => json!([
            "dict",
            items
                .iter()
                .map(|(k, x)| json!([canon(k), canon(x)]))
                .collect::<Vec<_>>()
        ]),
    }
}

fn from_canon(v: &Value) -> Yv {
    let a = v.as_array().unwrap();
    match a[0].as_str().unwrap() {
        "null" => Yv::None,
        "bool" => Yv::Bool(a[1].as_bool().unwrap()),
        "int" => Yv::Int(a[1].as_str().unwrap().parse().unwrap()),
        "str" => Yv::Str(a[1].as_str().unwrap().to_owned()),
        "list" => Yv::List(a[1].as_array().unwrap().iter().map(from_canon).collect()),
        "dict" => Yv::Dict(
            a[1].as_array()
                .unwrap()
                .iter()
                .map(|p| (from_canon(&p[0]), from_canon(&p[1])))
                .collect(),
        ),
        other => panic!("unsupported canon {other}"),
    }
}

/// The committed golden; `PYYAML_GOLDEN=<file>` points the same checks at another corpus generated the same way
/// (e.g. a large random one while porting).
fn golden() -> Value {
    let p = std::env::var("PYYAML_GOLDEN").unwrap_or_else(|_| {
        concat!(
            env!("CARGO_MANIFEST_DIR"),
            "/tests/fixtures/aiperf/pyyaml_golden.json"
        )
        .to_owned()
    });
    serde_json::from_str(&std::fs::read_to_string(p).unwrap()).unwrap()
}

#[test]
fn pyyaml_port_matches_cpython_on_the_golden_corpus() {
    check_corpus(&golden());
}

#[test]
fn pyyaml_port_matches_cpython_on_a_seeded_random_corpus() {
    let p = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/tests/fixtures/aiperf/pyyaml_fuzz_golden.json"
    );
    check_corpus(&serde_json::from_str(&std::fs::read_to_string(p).unwrap()).unwrap());
}

fn check_corpus(g: &Value) {
    let mut failures = Vec::new();
    for case in g["cases"].as_array().unwrap() {
        let text = case["text"].as_str().unwrap();
        let got = pyyaml::safe_load_value(text);
        match (&got, case.get("value"), case.get("error")) {
            (Ok(v), Some(want), None) => {
                if &canon(v) != want {
                    failures.push(format!("{text:?}: value {} != {}", canon(v), want));
                }
            }
            (Err(e), None, Some(want)) => {
                let (class, s, problem, line, is_yaml) = match e {
                    YamlError::Py(p) => (
                        p.class.to_owned(),
                        p.message.clone(),
                        p.message.clone(),
                        None,
                        false,
                    ),
                    y => (
                        y.class().to_owned(),
                        y.to_string(),
                        y.problem_or_str(),
                        y.problem_mark().map(|m| m.line + 1),
                        true,
                    ),
                };
                let want_str = want["str"].as_str().unwrap();
                let want_class = want["class"].as_str().unwrap();
                // KeyError's str() is repr(key); `problem` falls back to str(e) for non-marked errors
                if class != want_class
                    || s != want_str
                    || problem != want["problem"].as_str().unwrap()
                    || line != want["line"].as_u64().map(|l| usize::try_from(l).unwrap())
                    || is_yaml != want["yaml_error"].as_bool().unwrap()
                {
                    failures.push(format!(
                        "{text:?}:\n  got  {class} {s:?} problem={problem:?} line={line:?}\n  want {want_class} {want_str:?} problem={:?} line={}",
                        want["problem"], want["line"]
                    ));
                }
            }
            (other, _, _) => failures.push(format!("{text:?}: got {other:?}, want {case}")),
        }
        // yaml.compose: key lines of the top-level mapping
        let want_lines = &case["key_lines"];
        let got_lines = match pyyaml::compose(text) {
            Err(_) => Value::Null,
            Ok(doc) => {
                let mut out = Vec::new();
                if let Some(root) = doc.root.and_then(|r| doc.node(r))
                    && let NodeKind::Map(items) = &root.kind
                {
                    for (k, _) in items {
                        let kn = doc.node(*k).unwrap();
                        if let NodeKind::Scalar(s) = &kn.kind {
                            out.push(json!([s, kn.start.line + 1, kn.start.column + 1]));
                        }
                    }
                }
                Value::Array(out)
            }
        };
        if &got_lines != want_lines {
            failures.push(format!("{text:?}: key lines {got_lines} != {want_lines}"));
        }
    }
    assert!(
        failures.is_empty(),
        "{} mismatch(es):\n{}",
        failures.len(),
        failures.join("\n")
    );
}

#[test]
fn safe_dump_matches_cpython() {
    let g = golden();
    for d in g["dumps"].as_array().unwrap() {
        let data = from_canon(&d["data"]);
        let dumped = pyyaml::safe_dump(&data, &DumpOpts::SAFE_DUMP_UNSORTED);
        assert_eq!(dumped, d["yaml"].as_str().unwrap());
        // and it reads back as the same data
        assert_eq!(canon(&pyyaml::safe_load_value(&dumped).unwrap()), d["data"]);
    }
}
